  for change in select value from jsonb_array_elements($idecan_review_batch$[{"candidate":"b120eec64c784e8e063b858d90d0232a402d4c108da59432f81fb0894ac6f3ee","expected_status":"under_review","expected_payload":{"raw_text":"40. Rafael conta a Sandra que tem intenção de matar Raimundo e\npede opinião da amiga. Sandra, que secretamente desejava a\nmorte dessa mesma pessoa, incentiva que Rafael pratique\ndelito de homicídio contra Raimundo. Influenciado pelas\npalavras de Sandra, Rafael chama Raimundo para sair com o\nobjetivo de matá-lo. Todavia, poucas horas antes, Rafael\ndesiste e manda mensagem para Raimundo desmarcando o\nencontro.\nNessa hipótese, assinale a alternativa correta.\nA) Rafael e Sandra devem responder por tentativa de homicídio\npraticado em concurso de pessoas.\nB) Nem Rafael nem Sandra poderão ser responsabilizados\npenalmente.\nC) Apenas Rafael deve responder por tentativa de homicídio.\nD) Caso Rafael viesse, efetivamente, a matar Raimundo, Sandra\npoderia ser considerada coautora do delito.\nE) Apenas Sandra deve responder pelo delito de tentativa de\nhomicídio, a título de participação, pois Rafael beneficia-se da\ndesistência voluntária.","item_number":40,"source_pages":[13],"answer_in_official_document":"B","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"40. Rafael conta a Sandra que tem intenção de matar Raimundo e\npede opinião da amiga. Sandra, que secretamente desejava a\nmorte dessa mesma pessoa, incentiva que Rafael pratique\ndelito de homicídio contra Raimundo. Influenciado pelas\npalavras de Sandra, Rafael cha