:"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":1,"checked_at":"2026-10-23T00:46:40.971776+00:00","section_heading_ambiguous":false,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83736/idecan-2021-pc-ce-escrivao-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d","source_pages":[16]}}}},{"candidate":"3be7425c5782f100ec9df0a180c1d337c83d6e05470539e8aec26fb6289dc9a4","expected_status":"under_review","expected_payload":{"raw_text":"57. Conceitua-se o flagrante delito como a prisão ocorrida no\nmomento do cometimento do crime, no instante em que o\nsujeito pratica os elementos descritos no tipo penal. Portanto,\nocorre a prisão em flagrante no momento em que o indivíduo\né surpreendido cometendo a infração penal, seja ela tentada\nou consumada. Como espécie de medida cautelar, a prisão em\nflagrante possui determinadas características, À EXCEÇÃO\nDE UMA. Assinale-a.\nA) jurisdicionalidade\nB) provisoriedade\nC) homogeneidade\nD) acessoriedade\nE) informalidade","item_number":57,"source_pages":[16],"answer_in_official_document":"E","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"57. Conceitua-se o flagrante delito como a prisão ocorrida no\nmomento do cometimento do crime, no instante em que o\nsujeito pratica os elementos descritos no tipo penal. Portanto,\nocorre a prisão em flagrante no momento em que o indivíduo\né surpreendido cometendo a infração penal, seja ela tentada\nou consumada. Como espécie de medida cautelar, a prisão em\nflagrante possui determinadas características, À EXCEÇÃO\nDE UMA. Assinale-a.\nA) jurisdicionalidade\nB) provisoriedade\nC) homogeneidade\nD) acessoriedade\nE) informalidade","item_number":57,"source_pages":[16],"answer_in_official_document":"E","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":true,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/3be7425c5782f100ec9df0a180c1d337c83d6e05470539e8aec26fb6289dc9a4","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Características das cautelares e formalização do flagrante","observed_style":"teoria_doutrinaria","explanation":"Informalidade é a exceção indicada em E; o flagrante exige documentação e comunicação legais. A qualificação doutrinária do flagrante como cautelar ou pré-cautelar precisa ser delimitada, sem atribuir ao ato policial toda a jurisdicionalidade da prisão preventiva.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","doutrina_pendente"],"primary_evidence":[{"reference":"cpp:304","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"9b98604cf1bee226bfb0a5c839efd400df1b34adf535ef2a6480ff17dbe23146","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/304","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"cpp:306","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"1394ce6eb556f4f57ac6bd809a075532250f48581bfc95a5142dc32326583f14","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/306","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":1,"checked_at":"2026-10-23T00:46:40.971776+00:00","section_heading_ambiguous":false,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83736/idecan-2021-pc-ce-escrivao-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d","source_pages":[16]}}}},{"candidate":"99f310819c528b65459ffc0e2022bd954b77ae1de8a4b8d88e3442331214616b","expected_status":"under_review","expected_payload":{"raw_text":"58. Carlos foi investigado pela prática de furto qualificado sendo,\nposteriormente, denunciado pelo Ministério Público pelos\nmesmos fatos. Durante a investigação, foi realizado o\nreconhecimento de Carlos por meio de uma fotografia dele que\nconstava no sistema de identificação civil do Estado,\ndesatualizada há mais de trinta anos. No curso da ação penal,\no Magistrado determinou a realização do reconhecimento\npessoal, da seguinte forma: como a vítima requereu ao Juiz\nnão depor na presença do acusado, inicialmente a vítima\nvisualizou uma foto de Carlos tirada pelo celular do\nserventuário, confirmando ser ele; posteriormente, o\nMagistrado determinou que o réu ficasse atrás de uma porta e\nque a vítima olhasse para ele pela fresta da porta entreaberta,\na fim de que fosse confirmado que era Carlos quem teria\npraticado o crime. Exclusivamente com essas provas, Carlos,\nembora negasse a autoria dos fatos, foi condenado a uma\npena privativa de liberdade.\nAtento ao que foi narrado, assinale a alternativa correta em\nrelação ao procedimento de reconhecimento de pessoas.\nA) O reconhecimento de pessoas realizado em juízo está\nautorizado pela legislação processual e pode ser utilizado para\na condenação de Carlos, pois se trata de meio lícito de prova.\nB) A validade do reconhecimento do autor de infração não está\nobrigatoriamente vinculada à regra processual contida no art.\n226 do Código de Processo Penal, porquanto tal dispositivo\nveicula meras recomendações à realização do procedimento.\nC) O reconhecimento de pessoas, conforme realizado pelo\nMagistrado, está em desacordo com a legislação processual e\né inválido, não podendo servir de lastro probatório para\ncondenar Carlos.\nD) O reconhecimento fotográfico serve como prova apenas inicial\ne deve ser ratificado por reconhecimento presencial, assim\nque possível. E, caso elas tenham sido efetuadas sem a\nobservância dos preceitos legais, ainda serão válidos, pois\ntrata-se de meras recomendações legais.\nE) O reconhecimento de pessoas, da forma como foi realizado,\nserve para embasar a condenação de Carlos, já que a\nlegislação processual estabelece apenas exemplos de como\nse realizar o procedimento.","item_number":58,"source_pages":[17],"answer_in_official_document":"C","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"58. Carlos foi investigado pela prática de furto qualificado sendo,\nposteriormente, denunciado pelo Ministério Público pelos\nmesmos fatos. Durante a investigação, foi realizado o\nreconhecimento de Carlos por meio de uma fotografia dele que\nconstava no sistema de identificação civil do Estado,\ndesatualizada há mais de trinta anos. No curso da ação penal,\no Magistrado determinou a realização do reconhecimento\npessoal, da seguinte forma: como a vítima requereu ao Juiz\nnão depor na presença do acusado, inicialmente a vítima\nvisualizou uma foto de Carlos tirada pelo celular do\nserventuário, confirmando ser ele; posteriormente, o\nMagistrado determinou que o réu ficasse atrás de uma porta e\nque a vítima olhasse para ele pela fresta da porta entreaberta,\na fim de que fosse confirmado que era Carlos quem teria\npraticado o crime. Exclusivamente com essas provas, Carlos,\nembora negasse a autoria dos fatos, foi condenado a uma\npena privativa de liberdade.\nAtento ao que foi narrado, assinale a alternativa correta em\nrelação ao procedimento de reconhecimento de pessoas.\nA) O reconhecimento de pessoas realizado em juízo está\nautorizado pela legislação processual e pode ser utilizado para\na condenação de Carlos, pois se trata de meio lícito de prova.\nB) A validade do reconhecimento do autor de infração não está\nobrigatoriamente vinculada à regra processual contida no art.\n226 do Código de Processo Penal, porquanto tal dispositivo\nveicula meras recomendações à realização do procedimento.\nC) O reconhecimento de pessoas, conforme realizado pelo\nMagistrado, está em desacordo com a legislação processual e\né inválido, não podendo servir de lastro probatório para\ncondenar Carlos.\nD) O reconhecimento fotográfico serve como prova apenas inicial\ne deve ser ratificado por reconhecimento presencial, assim\nque possível. E, caso elas tenham sido efetuadas sem a\nobservância dos preceitos legais, ainda serão válidos, pois\ntrata-se de meras recomendações legais.\nE) O reconhecimento de pessoas, da forma como foi realizado,\nserve para embasar a condenação de Carlos, já que a\nlegislação processual estabelece apenas exemplos de como\nse realizar o procedimento.","item_number":58,"source_pages":[17],"answer_in_official_document":"C","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":true,"historical_answer_letter":"C","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/99f310819c528b65459ffc0e2022bd954b77ae1de8a4b8d88e3442331214616b","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Reconhecimento de pessoas","observed_style":"caso_pratico","explanation":"A forma narrada não segue o art. 226 e o gabarito C a considera inválida. Conferir os precedentes atuais sobre obrigatoriedade do procedimento e limites de prova independente; não confundir confirmação posterior sugestiva com saneamento do primeiro reconhecimento.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","jurisprudencia_pendente"],"primary_evidence":[{"reference":"cpp:226","title":"Código de Processo Penal","url":"https://www2.camara.leg.br/legin/fed/declei/1940-1949/decreto-lei-3689-3-outubro-1941-322206-normaatualizada-pe.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"e6e68e8afc1da9aeac8970fb106d7d49e88eec11d67db3b704c8c6db65c2fe0f","excerpt_sha256":"29b6a6a6b0e2c72e0f1884ba0be530391eaaa4e0f11d4c77d6274c43f2525376","excerpt_artifact":"fontes-e-excertos.json#/sources/cpp/excerpts/226","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":1,"checked_at":"2026-10-23T00:46:40.971776+00:00","section_heading_ambiguous":false,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83736/idecan-2021-pc-ce-escrivao-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d","source_pages":[17]}}}},{"candidate":"38f6b17b07dc830288e6a47382aad2975cd1f9f3296903d87cb9e6574d74008e","expected_status":"under_review","expected_payload":{"raw_text":"59. A Lei de Execuções Penais – 7.210/84 – é considerada um\ndiploma moderno, que reconhece o preso como sujeito de\ndireitos e estabelece deveres e direitos aos condenados.A\nrespeito das disposições legais contidas na Lei 7.210/84, NÃO\né correto afirmar que\nA) o cometimento de falta grave durante a execução da pena\nprivativa de liberdade interrompe o prazo para a obtenção da\nprogressão no regime de cumprimento da pena, caso em que\no reinício da contagem do requisito objetivo terá como base a\npena remanescente.\nB) são considerados órgãos da execução penal o Conselho da\nComunidade, o Ministério Público, o Conselho Penitenciário, a\nDefensoria Pública, o Patronato, os Agentes Penitenciários, o\nConselho Nacional de Política Criminal e Penitenciária, o Juízo\nda Execução e os Departamentos Penitenciários.\nC) a remissão de parte do tempo de execução da pena, por\ntrabalho ou por estudo, será contado da seguinte forma: 1 (um)\ndia de pena a cada 12 (doze) horas de frequência escolar\ndivididas, no mínimo, em 3 (três) dias; 1 (um) dia de pena a\ncada 3 (três) dias de trabalho.\nD) quando houver condenação por mais de um crime, no mesmo\nprocesso ou em processos distintos, a determinação do\nregime de cumprimento será feita pelo resultado da soma ou\nunificação das penas, observada, quando for o caso, a\ndetração ou remição.\nE) a LEP se aplicará igualmente ao preso provisório e ao\ncondenado pela Justiça Eleitoral ou Militar, quando recolhido a\nestabelecimento sujeito à jurisdição ordinária.","item_number":59,"source_pages":[17],"answer_in_official_document":"B","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"59. A Lei de Execuções Penais – 7.210/84 – é considerada um\ndiploma moderno, que reconhece o preso como sujeito de\ndireitos e estabelece deveres e direitos aos condenados.A\nrespeito das disposições legais contidas na Lei 7.210/84, NÃO\né correto afirmar que\nA) o cometimento de falta grave durante a execução da pena\nprivativa de liberdade interrompe o prazo para a obtenção da\nprogressão no regime de cumprimento da pena, caso em que\no reinício da contagem do requisito objetivo terá como base a\npena remanescente.\nB) são considerados órgãos da execução penal o Conselho da\nComunidade, o Ministério Público, o Conselho Penitenciário, a\nDefensoria Pública, o Patronato, os Agentes Penitenciários, o\nConselho Nacional de Política Criminal e Penitenciária, o Juízo\nda Execução e os Departamentos Penitenciários.\nC) a remissão de parte do tempo de execução da pena, por\ntrabalho ou por estudo, será contado da seguinte forma: 1 (um)\ndia de pena a cada 12 (doze) horas de frequência escolar\ndivididas, no mínimo, em 3 (três) dias; 1 (um) dia de pena a\ncada 3 (três) dias de trabalho.\nD) quando houver condenação por mais de um crime, no mesmo\nprocesso ou em processos distintos, a determinação do\nregime de cumprimento será feita pelo resultado da soma ou\nunificação das penas, observada, quando for o caso, a\ndetração ou remição.\nE) a LEP se aplicará igualmente ao preso provisório e ao\ncondenado pela Justiça Eleitoral ou Militar, quando recolhido a\nestabelecimento sujeito à jurisdição ordinária.","item_number":59,"source_pages":[17],"answer_in_official_document":"B","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":true,"historical_answer_letter":"B","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/38f6b17b07dc830288e6a47382aad2975cd1f9f3296903d87cb9e6574d74008e","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Órgãos e regras da execução penal","observed_style":"confronto_de_regras","explanation":"A enumeração do art. 61 não inclui genericamente agentes penitenciários como órgão. B é o gabarito histórico da exceção; conferir também os demais dispositivos, as alterações do art. 112 e o erro material remissão/remição na alternativa C.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto","erro_terminologico_na_fonte"],"primary_evidence":[{"reference":"lep:2","title":"Lei de Execução Penal","url":"https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7210-11-julho-1984-356938-normaatualizada-pl.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"980c833062f81f00251cc0d0f12a4fcde36a04c2658b3826b08d571f7a4f85ea","excerpt_sha256":"3693e74358a93c4d74ee736ed748f94063d4ebee5420c0a10d80212949e4af77","excerpt_artifact":"fontes-e-excertos.json#/sources/lep/excerpts/2","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."},{"reference":"lep:61","title":"Lei de Execução Penal","url":"https://www2.camara.leg.br/legin/fed/lei/1980-1987/lei-7210-11-julho-1984-356938-