entar\n_____________________ para que seja instaurado(a)\n_____________________ destinado(a) a apurar a prática de\nato de improbidade.\nAssinale a alternativa que apresente a sequência correta dos\ntermos empregados.\nA) cidadão – ao Tribunal de Contas – investigação\nB) pessoa – ao Tribunal de Contas – inquérito\nC) cidadão – à Polícia Civil – inquérito\nD) cidadão – ao Ministério Público – inquérito\nE) pessoa – à autoridade administrativa competente –\ninvestigação","item_number":67,"source_pages":[19],"answer_in_official_document":"E","answer_key_requires_clarification":false,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":true,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"parecer_individual_de_continuacao_com_publicacao_retida","reviewed_at":"2026-10-23T00:46:40.973169Z","publication_approved":false,"answer_verified":false,"historical_answer_letter_checked":true,"historical_answer_letter":"E","context_complete":false,"visual_checked":false,"literal_pdf_text_checked":true,"literal_check_artifact":"cotejo-literal-pdf.json#/c56d418ed86617c54cc332f00a0112caa4c47d54e43b9d3378e6b851ff1caefe","legal_current":false,"legal_review_status":"certificacao_integral_pendente","question_format":"multiple_choice","observed_topic":"Representação por improbidade","observed_style":"preenchimento_de_lacunas","explanation":"O art. 14 confirma qualquer pessoa, autoridade administrativa competente e investigação. A letra E não se limita a cidadão ou a provocação do Tribunal de Contas; faltam os demais requisitos de publicação e cotejo do Planalto.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","revisao_final_de_contexto_e_formatacao","vigencia_integral_nao_certificada_no_planalto"],"primary_evidence":[{"reference":"improbidade:14","title":"Lei de Improbidade Administrativa","url":"https://www2.camara.leg.br/legin/fed/lei/1992/lei-8429-2-junho-1992-357452-normaatualizada-pl.html","checked_at":"2026-10-23T00:43:16.058684Z","verified":true,"sha256":"ac5ffb8bcb800556b9cd9563bcffe957c81c3170fe455c1da526013a4ee89010","excerpt_sha256":"a025161b5f73310d26a2ae40bb8899aee71e03b8fcc19f5ba12e2e90508b138c","excerpt_artifact":"fontes-e-excertos.json#/sources/improbidade/excerpts/14","scope":"Texto atualizado alternativo oficial; não substitui certificação exigida no Planalto nem julgamento de cada tese."}],"answer_key_evidence":{"url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","page":1,"checked_at":"2026-10-23T00:46:40.971776+00:00","section_heading_ambiguous":false,"scope":"Letra transcrita conferida no documento; isso não certifica a validade jurídica atual."},"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83736/idecan-2021-pc-ce-escrivao-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d","source_pages":[19]}}}}]$idecan_review_batch$::jsonb) loop
    select * into stored from public.question_corpus_candidates where id=change->>'candidate' for update;
    if not found then raise exception 'Candidato não encontrado; aplique antes o acervo de 200 itens'; end if;
    if stored.content_status=change->>'next_status' and stored.payload=change->'next_payload' then continue; end if;
    if stored.content_status is distinct from change->>'expected_status'
      or stored.payload is distinct from change->'expected_payload' then
      raise exception 'Revisão desatualizada: decisão existente preservada; recarregue o candidato';
    end if;
    if stored.content_status <> 'under_review' then raise exception 'Decisão anterior protegida'; end if;
    if change->'next_payload'->'raw_text' is distinct from stored.payload->'raw_text' then
      raise exception 'Extração original protegida';
    end if;
    if change->'next_payload' ? 'publication'
      or change#>>'{next_payload,individual_review,publication_approved}' is distinct from 'false' then
      raise exception 'Este lote não permite publicação';
    end if;
    insert into public.question_corpus_review_audit(candidate_id,previous_status,next_status,previous_payload,next_payload,reviewer_id)
    values(stored.id,stored.content_status,change->>'next_status',stored.payload,change->'next_payload',auth.uid());
    update public.question_corpus_candidates set content_status=change->>'next_status',payload=change->'next_payload' where id=stored.id;
  end loop;
end $review$;
commit;
-- reviewed significa parecer registrado, não autorização de publicação.
select s.title,c.content_status,count(*) as candidates
from public.question_corpus_sources s join public.question_corpus_candidates c on c.corpus_id=s.id
where s.id in ('56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe','a835d92983601375c77355a50f68bdc77092e4fb88fdb9686ff453b8ed2fd57d')
group by s.title,c.content_status order by s.title,c.content_status;
